<script setup>
import { computed, ref } from 'vue'
import { useMesStore } from '../store'
const props=defineProps({elements:{type:Array,default:()=>[]},step:{type:Object,default:null},model:{type:String,default:''},task:{type:Object,default:null},activeId:{type:String,default:''},editable:{type:Boolean,default:false}})
const emit=defineEmits(['select','move']),store=useMesStore(),dragging=ref(null)
const context=computed(()=>{const p=props.step?.parameters||[],values=props.task?.logs?.[props.step?.stepNo]?.values||{};return{stepTitle:props.step?.title||'工序标题',stepNo:String(props.step?.stepNo||'01').padStart(2,'0'),paramName1:p[0]?.name||'参数名称',paramValue1:values[1]||p[0]?.referenceValue||'参考值',paramName2:p[1]?.name||'参数名称',paramValue2:values[2]||p[1]?.referenceValue||'参考值',paramName3:p[2]?.name||'参数名称',paramValue3:values[3]||p[2]?.referenceValue||'参考值',progress:props.step?`${props.step.stepNo} / ${store.activeSteps.length}`:`01 / ${store.steps.length}`,model:props.model||store.state.processRecord.model,steelNo:props.task?.steelNo||store.state.steelNo||'钢印号',taskNo:props.task?.id||'任务号',operator:props.task?.operatorName||store.state.operatorName}})
function resolveText(text=''){return text.replace(/{{(\w+)}}/g,(_,key)=>context.value[key]??'')}
function styleFor(el){return{left:`${el.x/19.2}%`,top:`${el.y/10.8}%`,transform:`rotate(${el.rotation||0}deg) scale(${el.scale||1})`,zIndex:el.zIndex||1,color:el.color||'#EFF2F0',fontSize:`clamp(8px,${((el.fontSize||42)/19.2).toFixed(3)}cqw,${el.fontSize||42}px)`}}
function startDrag(event,el){emit('select',el.id);if(!props.editable)return;event.preventDefault();dragging.value={id:el.id,startX:event.clientX,startY:event.clientY,x:el.x,y:el.y,rect:event.currentTarget.parentElement.getBoundingClientRect()};window.addEventListener('pointermove',onMove);window.addEventListener('pointerup',stopDrag,{once:true})}
function onMove(event){const d=dragging.value;if(!d)return;emit('move',{id:d.id,x:Math.max(0,Math.min(1919,Math.round(d.x+(event.clientX-d.startX)*1920/d.rect.width))),y:Math.max(0,Math.min(1079,Math.round(d.y+(event.clientY-d.startY)*1080/d.rect.height)))})}
function stopDrag(){dragging.value=null;window.removeEventListener('pointermove',onMove)}
</script>
<template><div class="projection-canvas" :class="{editable}"><div class="projection-grid"></div><div v-if="!elements.length" class="projection-empty"><Monitor/><strong>当前步骤未配置投影元素</strong><span>可在工艺步骤中选择投影模板</span></div><div v-for="el in elements" :key="el.id" class="projection-element" :class="{selected:editable&&activeId===el.id,'is-blink':el.blink}" :style="styleFor(el)" @pointerdown="startDrag($event,el)"><img v-if="el.type==='icon'" :src="store.iconUrl(el.iconName)" :alt="el.iconName" draggable="false" class="projection-icon"/><span v-else class="projection-text">{{resolveText(el.text)}}</span></div><span class="canvas-corner top-left"></span><span class="canvas-corner top-right"></span><span class="canvas-corner bottom-left"></span><span class="canvas-corner bottom-right"></span></div></template>
